css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .44); position: relative; }
.loader .grid { position: absolute; left: 0; right: 0; top: 0; height: 72%; display: grid; grid-template-columns: repeat(6, 1fr); grid-auto-rows: 1fr; gap: 4%; }
.loader span { border-radius: 3px; background: color-mix(in srgb, var(--accent) 16%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 35%, transparent); animation: sector-check calc(var(--loader-speed) * 2.8) steps(1, end) infinite; }
.loader span:nth-of-type(2) { animation-delay: calc(var(--loader-speed) * .2); }
.loader span:nth-of-type(3) { animation-delay: calc(var(--loader-speed) * .4); }
.loader span:nth-of-type(4) { animation-delay: calc(var(--loader-speed) * .6); }
.loader span:nth-of-type(5) { animation-delay: calc(var(--loader-speed) * .8); }
.loader span:nth-of-type(6) { animation-delay: calc(var(--loader-speed) * 1); }
.loader span:nth-of-type(7) { animation-delay: calc(var(--loader-speed) * 1.2); }
.loader span:nth-of-type(8) { animation-delay: calc(var(--loader-speed) * 1.4); }
.loader span:nth-of-type(9) { animation-delay: calc(var(--loader-speed) * 1.6); }
.loader span:nth-of-type(10) { animation-delay: calc(var(--loader-speed) * 1.8); }
.loader span:nth-of-type(11) { animation-delay: calc(var(--loader-speed) * 2); }
.loader span:nth-of-type(12) { animation-delay: calc(var(--loader-speed) * 2.2); }
.loader .caret { position: absolute; left: 0; bottom: 2%; width: 8%; height: 16%; background: var(--accent-2); animation: sector-caret calc(var(--loader-speed) * .8) steps(1, end) infinite; }
@keyframes sector-check { 0%, 6% { background: color-mix(in srgb, var(--accent) 16%, transparent); } 7%, 20% { background: var(--accent-2); } 21%, 100% { background: var(--accent); } }
@keyframes sector-caret { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }
